package com.cheforder;
import android.Manifest; import android.app.Activity; import android.content.Intent; import android.content.pm.PackageManager; import android.os.Bundle; import android.speech.RecognizerIntent; import android.widget.*; import java.util.*;
public class MainActivity extends Activity { LinearLayout list; ArrayList<String> items=new ArrayList<>(); public void onCreate(Bundle b){super.onCreate(b); LinearLayout r=new LinearLayout(this); r.setOrientation(LinearLayout.VERTICAL); r.setPadding(28,40,28,28); TextView t=new TextView(this); t.setText("ChefOrder\nVoice purchasing assistant"); t.setTextSize(28); r.addView(t); Button v=new Button(this); v.setText("🎤  TAP TO SPEAK"); r.addView(v); TextView h=new TextView(this); h.setText("\nTry: Add 10 kilos of chicken breast and 5 kilos of onions.\n"); h.setTextSize(16); r.addView(h); list=new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL); r.addView(list); Button c=new Button(this); c.setText("CONFIRM ORDER"); r.addView(c); v.setOnClickListener(x->listen()); c.setOnClickListener(x->Toast.makeText(this,items.isEmpty()?"No items yet.":"Order confirmed locally.",Toast.LENGTH_SHORT).show()); setContentView(r);} void listen(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},10);return;} Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH); i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM); startActivityForResult(i,20);} protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==20&&c==RESULT_OK&&d!=null){ArrayList<String>s=d.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(s!=null&&!s.isEmpty()){items.add(s.get(0));TextView row=new TextView(this);row.setText("• "+s.get(0));row.setTextSize(18);row.setPadding(0,12,0,12);list.addView(row);}}}}
